<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class UpbringingSurveyController extends Controller{
private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('upbringing_head'),403);}
public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('upbringing_surveys as s')->where('academic_period_id',$p->id)->select('s.*',DB::raw('(select count(*) from upbringing_survey_questions q where q.survey_id=s.id) questions'),DB::raw('(select count(distinct respondent_key) from upbringing_survey_responses x where x.survey_id=s.id) responses'))->orderByDesc('id')->get();return view('upbringing.surveys',compact('rows'));}
public function store(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['title'=>'required|string|max:255','description'=>'nullable|string|max:3000','audience'=>'required|in:students,parents,teachers,employees,external','starts_on'=>'nullable|date','ends_on'=>'nullable|date']);DB::table('upbringing_surveys')->insert($d+['academic_period_id'=>$p->id,'created_by'=>$r->user()->id,'status'=>'draft','created_at'=>now(),'updated_at'=>now()]);return back();}
public function show(Request $r,$id){$this->ok($r);$survey=DB::table('upbringing_surveys')->find($id);abort_if(!$survey,404);$questions=DB::table('upbringing_survey_questions')->where('survey_id',$id)->orderBy('sort_order')->get();$answers=DB::table('upbringing_survey_responses')->where('survey_id',$id)->select('question_id','answer',DB::raw('COUNT(*) total'))->groupBy('question_id','answer')->get()->groupBy('question_id');return view('upbringing.survey',compact('survey','questions','answers'));}
public function question(Request $r,$id){$this->ok($r);$d=$r->validate(['question'=>'required|string|max:2000','type'=>'required|in:single,multiple,scale,text','options'=>'nullable|string|max:5000']);DB::table('upbringing_survey_questions')->insert(['survey_id'=>$id,'question'=>$d['question'],'type'=>$d['type'],'options'=>$d['options']?json_encode(array_values(array_filter(array_map('trim',preg_split('/[\r\n]+/',$d['options'])))),JSON_UNESCAPED_UNICODE):null,'sort_order'=>DB::table('upbringing_survey_questions')->where('survey_id',$id)->count()+1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function status(Request $r,$id){$this->ok($r);$d=$r->validate(['status'=>'required|in:draft,open,closed']);DB::table('upbringing_surveys')->where('id',$id)->update(['status'=>$d['status'],'updated_at'=>now()]);return back();}
}